let pendingImport=null,pendingEventEdit=null,receivingSelection=false,payingSelection=false;
const receiptSelection=new Set();
let paymentCandidates=new Map();

const paths={wallet:'M3 6h16v14H3z M3 6V4h13 M15 11h6v5h-6z',home:'M3 10l9-7 9 7v11H3z M9 21v-8h6v8',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16',plus:'M12 5v14 M5 12h14',list:'M8 6h13 M8 12h13 M8 18h13 M3 6h.01 M3 12h.01 M3 18h.01',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 1 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',download:'M12 3v12 M7 10l5 5 5-5 M4 15v6h16v-6',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',alert:'M12 3L2 21h20z M12 9v5 M12 18h.01',arrow:'M5 12h14 M13 6l6 6-6 6',check:'M5 12l4 4L19 6',chart:'M4 3v18h18 M7 15l4-5 4 3 6-8',phone:'M7 2h10v20H7z M11 18h2',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',pie:'M21 12a9 9 0 1 1-9-9v9z M15 3v6h6a9 9 0 0 0-6-6',food:'M4 3v7h6V3 M7 3v18 M17 3v18 M17 3c-4 4-4 10 0 10',car:'M4 10l2-6h12l2 6 M3 10h18v8H3z M6 18v3 M18 18v3 M6 14h1 M17 14h1',heart:'M12 21C-6 10 6-1 12 7 18-1 30 10 12 21z',gift:'M3 8h18v4H3z M5 12v9h14v-9 M12 8v13 M12 8C3 9 4 0 9 3z M12 8C21 9 20 0 15 3z',search:'M21 21l-6-6 M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',wifi:'M2 8a16 16 0 0 1 20 0 M5 12a11 11 0 0 1 14 0 M8 16a6 6 0 0 1 8 0 M12 20h.01',arrowDown:'M12 4v16 M6 14l6 6 6-6',arrowUp:'M12 20V4 M6 10l6-6 6 6',signal:'M4 19v-3 M9 19v-7 M14 19V8 M19 19V4',battery:'M2 7h18v10H2z M23 10v4 M5 10h12v4H5z'};
const chartColors=['#f59e0b','#3b82f6','#f43f5e','#6366f1','#a855f7','#14b8a6','#10b981','#6b7280','#bf5af2','#64d2ff','#ffd60a'];
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.wallet}"/></svg>`;
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateText=d=>d?new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(d+'T12:00:00Z')).replace('.',''):'Sem data';
const monthName=m=>new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(new Date(m+'-01T12:00:00Z'));
const currencyInput=n=>n===null||n===undefined?'':(n/100).toFixed(2).replace('.',',');

function cardSettings(){
 return `<section class="card" id="cards-settings"><div class="row-head"><h2>Meus cartões</h2><button class="btn smallbtn" data-action="new-card">Adicionar cartão</button></div>
 <p class="help">Cadastre os dias uma vez. As próximas compras usam esse calendário automaticamente.</p>
 ${cardsForState(state()).map(c=>`<div class="listrow"><div class="body"><strong>${h(c.name)}</strong><span class="small muted">Vence: ${c.dueDay?'dia '+c.dueDay:'informar'} · Fecha: ${c.closingDay?'dia '+c.closingDay:'informar'}</span></div><button class="textbtn" data-action="edit-card" data-id="${h(c.id)}" aria-label="Editar cartão ${h(c.name)}">Editar</button></div>`).join('')||'<p class="empty">Adicione seu primeiro cartão.</p>'}
 <p class="help">Compras no dia do fechamento entram na fatura seguinte. Os dias podem variar no banco; confira a prévia e ajuste um movimento na Agenda quando necessário. Alterações no cadastro valem para novas compras.</p></section>`;
}
function cardModal(id){
 const c=cardsForState(state()).find(c=>c.id===id)||{id:crypto.randomUUID(),name:'',dueDay:null,closingDay:null};
 modal(id?'Editar cartão':'Adicionar cartão',`<form id="card-form" data-id="${h(c.id)}"><div class="field"><label for="card-name">Nome do cartão</label><input id="card-name" name="name" required maxlength="80" value="${h(c.name)}" placeholder="Ex.: Meu cartão"></div><div class="form-grid"><div class="field"><label for="card-due-day">Dia do vencimento</label><input id="card-due-day" name="dueDay" type="number" inputmode="numeric" min="1" max="31" required value="${c.dueDay??''}" placeholder="Ex.: 3"></div><div class="field"><label for="card-closing-day">Dia do fechamento</label><input id="card-closing-day" name="closingDay" type="number" inputmode="numeric" min="1" max="31" required value="${c.closingDay??''}" placeholder="Ex.: 25"></div></div><p class="help">Use o fechamento e o vencimento informados pelo seu banco. Em meses curtos, um dia que não existe passa para o último dia do mês.</p><p class="form-error" role="alert"></p><button class="btn full" type="submit">Salvar cartão neste aparelho</button></form>`);
}
function updatePaymentFields(){
 const form=document.querySelector('#purchase-form');if(!form)return;
 const method=form.querySelector('#purchase-method').value,credit=method==='Cartão de Crédito',bank=method==='Cartão de Débito'||credit;
 form.querySelector('#purchase-payment').value=credit?form.querySelector('#purchase-bank').value:method==='Dinheiro'||['VR','VA'].includes(method)?method:'Pix';
 form.querySelector('#bank-select-container').hidden=!bank;form.querySelector('#credit-fields').hidden=!credit;
 if(!credit)form.querySelector('#purchase-installments').value='1';
 const card=cardsForState(state()).find(c=>c.id===form.querySelector('#purchase-bank').value);
 form.querySelector('#purchase-card-info').textContent=card?.dueDay&&card?.closingDay?`${card.name}: fecha dia ${card.closingDay}, vence dia ${card.dueDay}.`:'Cadastre fechamento e vencimento em Ajustes.';
 const split=form.querySelector('#toggle-split').checked;form.querySelector('#split-fields-panel').hidden=!split;form.querySelector('#owner-field').hidden=split;
 const income=form.dataset.type==='income';form.querySelector('#expense-fields').hidden=income;form.querySelector('#income-fields').hidden=!income;
}
function purchaseInput(form,id){
 const p=Object.fromEntries(new FormData(form));p.id=id;p.amount=parseMoney(p.amount);p.paymentMethod=p.method;
 if(p.method==='Cartão de Débito')p.bankId=p.bank;
 if(form.querySelector('#toggle-split').checked)p.split={person:p.splitPerson,percent:Number(p.splitPercent),received:p.splitStatus==='Pago'};
 return p;
}
function cardOverview(s){
 const cards=cardsForState(s),rows=ledgerForMonth(s,historyMonth,{type:'expense'}),tones=[['#fb923c','#ec70002a'],['#60a5fa','#0a84ff25'],['#4ade80','#30d1581a'],['#fb7185','#cc092f25'],['#c084fc','#820ad12d']];
 return `<section class="cards-carousel-section"><div class="row-head"><h2>Cartões · todas as pessoas</h2><span class="small muted">${cards.length} cartões</span></div><div class="cards-carousel" role="list" aria-label="Gastos por cartão">${cards.map((c,i)=>{const tone=tones[i%tones.length],amount=historyTotal(rows.filter(r=>r.payment===c.id));return `<article class="credit-mini" role="listitem" style="--bank-color:${tone[0]};--bank-tint:${tone[1]}"><div class="row-head"><span class="bank-name">${h(c.name)}</span>${icon('wifi')}</div><div><small>Total do período · ${h(monthName(historyMonth).split(' de ')[0])}</small><strong>${money(amount)}</strong></div></article>`;}).join('')||'<p class="empty">Cadastre seu cartão em Ajustes.</p>'}</div></section>`;
}

let doc=null,tab='home',busy=false,filterMonth=todayBR().slice(0,7),historyMonth=todayBR().slice(0,7),historyPerson='JEFFERSON',agendaPerson='Todos',homePerson='JEFFERSON',historySearch='',statusFilter='open',toastTimer,transactionType='all',transactionCategory='ALL',transactionPerson='Todos',analyticsMode='category',modalType='expense';
const people=['JEFFERSON','CAMILA','FATIMA'];
const allPeople=()=>[...new Set([...people,...(doc?state().purchases.flatMap(p=>[p.person,p.split?.person]):[]),...(doc?state().history.map(r=>r.person):[])].filter(Boolean))];
const personOptions=(selected,shared=false)=>['Todos',...allPeople(),...(shared?['Compartilhado']:[])].map(p=>`<option ${selected===p?'selected':''}>${p}</option>`).join('');
const state=()=>doc.state;
const notify=(text,error=false)=>{const el=document.querySelector('#toast');el.textContent=text;el.style.background=error?'#7f1d1d':'#163d78';el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),5000);};
function blankState(){return {version:1,settings:{balance:0,asOf:todayBR(),reconciled:false,essentials:null,safety:0,monthlyLimit:null,benefits:{VR:null,VA:null},benefitMonthly:{VR:0,VA:0}},events:[],purchases:[],history:[],sources:[]};}
async function persist(next){if(busy)throw new Error('Aguarde o salvamento atual.');validateState(next);busy=true;try{doc=await writeControl(next,doc?.revision||0);render();return doc;}finally{busy=false;}}
function welcome(){return `<main class="welcome"><div class="brand-mark">${icon('wallet')}</div><p class="eyebrow">Simples, pessoal e no seu aparelho</p><h1>Seu dinheiro.<br>Mais clareza.</h1><p class="muted">Saiba quanto está livre para gastar e registre uma compra em poucos toques.</p><ul><li>Dados guardados somente neste navegador ou aplicativo instalado.</li><li>Sem conta, sem login e sem envio de dados financeiros.</li><li>Seu backup em arquivo permite recuperar ou transferir o controle.</li></ul><button class="btn" data-action="import">${icon('download')} Importar meu controle inicial</button><button class="btn ghost" data-action="blank">Começar um controle vazio</button><p class="footer-note">No iPhone: Safari → Compartilhar → Adicionar à Tela de Início. Abra o ícone instalado e importe o arquivo de backup ali. Não use navegação privada.</p></main>`;}
function render(){
 const app=document.querySelector('#app');if(!doc){app.className='onboarding';app.innerHTML=welcome();return;}app.className='phone-frame';
 const time=new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit'}).format(new Date());
 app.innerHTML=`<div class="dynamic-island" aria-hidden="true"><i></i><b></b></div><div class="status-bar" aria-hidden="true"><time>${time}</time><div>${icon('signal')}${icon('wifi')}${icon('battery')}</div></div><main id="app-viewport" class="shell">${tab==='home'?home():tab==='agenda'?agenda():tab==='history'?history():tab==='analytics'?analytics():settings()}</main><nav aria-label="Navegação principal">${[['home','home','Início'],['history','list','Transações'],['new','plus','Nova transação'],['analytics','pie','Análise'],['settings','settings','Ajustes']].map(([id,ic,label])=>`<button data-action="nav" data-tab="${id}" class="${id==='new'?'new':tab===id||id==='history'&&tab==='agenda'?'active':''}" ${tab===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></button>`).join('')}</nav><div class="home-indicator" aria-hidden="true"></div>`;
}
function eventRow(e){const day=e.date?.slice(-2)||'—',month=e.date?dateText(e.date).slice(3):'data';return `<div class="listrow"><span class="datebox"><b>${h(day)}</b>${h(month)}</span><div class="body"><strong>${h(e.description)}</strong><span class="small muted">${h(paymentName(state(),e.account||'Conta'))} · ${h(e.person||'JEFFERSON')} ${e.partialPaid?'· <span class="badge warn">Restante após pagar '+money(e.partialPaid)+'</span>':''} ${e.review?'· <span class="badge warn">Conferir</span>':''} ${e.status==='deferred'?'<span class="badge red">Adiado</span>':''} ${!e.confirmed&&e.direction==='in'?'<span class="badge warn">Não confirmado</span>':''}</span>${installmentBadge(e)}</div><button class="textbtn amount ${e.direction==='in'?'positive':''}" data-action="event" data-id="${h(e.id)}" aria-label="Abrir ${h(e.description)}">${e.direction==='in'?'+':'−'}${money(e.amount)}</button></div>`;}
function home(){
 const s=state(),d=dashboard(s),rows=ledgerForMonth(s,historyMonth),summary=monthOverview(s,historyMonth);
 const income=summary.income,expense=summary.personalExpenses,pending=s.events.filter(e=>e.kind==='reimbursement'&&e.status==='planned'&&(!e.date||e.date<monthDate(historyMonth+'-01',2)));
 return `<div class="page-head greeting"><div><p class="eyebrow">Bem-vindo de volta</p><h1>Jefferson</h1></div><div class="profile-avatar" aria-label="Jefferson"><span>J</span></div></div>
 <section class="hero"><div class="row-head"><span class="eyebrow">Saldo real da conta</span><span class="sync-badge">${navigator.onLine?'Neste aparelho':'Offline'}</span></div><div class="big-money ${summary.balance<0?'negative':''}">${money(summary.balance)}</div><p class="balance-reference">Conferido em ${dateText(s.settings.asOf)} · sem limite do LIS</p><div class="hero-bottom"><div><i class="metric-icon positive">${icon('arrowDown')}</i><div><span>Receitas do período</span><strong class="positive">${money(income)}</strong></div></div><div><i class="metric-icon negative">${icon('arrowUp')}</i><div><span>Despesas em meu nome</span><strong class="negative">${money(expense)}</strong></div></div></div><div class="safe-limit"><span>Livre para gastar agora</span><strong>${money(d.free)}</strong></div><button class="hero-note" data-action="nav" data-tab="settings">${d.incomplete?'Conferência inicial pendente · conferir →':`Limite seguro até ${dateText(d.until)} · saldo da conta ${money(s.settings.balance)}`}</button></section>
 <div class="period-control"><label for="home-month">Período</label><input type="month" id="home-month" aria-label="Mês do painel" value="${historyMonth}"></div>
 <details class="month-audit"><summary>Conferir os dados de ${monthName(historyMonth)}</summary><p>${summary.sourceCount} registros da planilha · ${summary.purchasesCount} compras novas no aplicativo${summary.projectedCount?' · '+summary.projectedCount+' parcelas previstas da planilha':''}</p><div class="row-head"><span>Planilha · minha parte</span><strong>${money(summary.sourceOwn)}</strong></div><div class="row-head"><span>Planilha · todas as pessoas</span><strong>${money(summary.sourceAll)}</strong></div><div class="row-head"><span>Outros compromissos pessoais</span><strong>${money(summary.personalExpenses-summary.sourceOwn)}</strong></div><p>O saldo da conta é o informado em Ajustes. Receitas e despesas abaixo seguem o mês selecionado. Benefícios ficam separados.</p></details>
 ${summary.pendingIncome?'<p class="import-note">Entradas ainda não confirmadas: <strong>'+money(summary.pendingIncome)+'</strong>. Elas aparecem em Transações, mas não liberam dinheiro para gastar.</p>':''}
 ${summary.sharedExpenses?'<p class="import-note">Faturas compartilhadas: <strong>'+money(summary.sharedExpenses)+'</strong>. Elas estão no total dos cartões e em Transações → Todas; confira as partes na Agenda.</p>':''}
 <button class="btn quick-action" data-action="purchase">${icon('plus')} Nova Transação / Dividir</button>${cardOverview(s)}
 <section class="split-summary"><div class="row-head"><h2>${icon('users')} Resumo de divisões</h2><span class="small muted">${pending.length} ${pending.length===1?'pendente':'pendentes'}</span></div><div class="row-head"><span>A receber de outras pessoas:</span><strong class="positive">${money(pending.reduce((n,e)=>n+e.amount,0))}</strong></div><p>Acertos até ${dateText(previousDay(monthDate(historyMonth+'-01',2)))} e sem data · recebimentos separados dos pagamentos.</p></section>
 <div class="row-head recent-heading"><h2>Últimas transações</h2><button class="textbtn" data-action="nav" data-tab="history">Ver todas</button></div><div class="transaction-list">${rows.slice(0,4).map(transactionCard).join('')||'<p class="empty">Nenhuma transação neste mês.</p>'}</div>
 <details class="financial-details"><summary>Seu saldo e compromissos</summary><div class="row-head"><span>Saldo real da conta</span><strong class="${s.settings.balance<0?'negative':''}">${money(s.settings.balance)}</strong></div><div class="row-head"><span>Dívidas adiadas · reservadas</span><strong class="negative">${money(d.deferred)}</strong></div><div class="row-head"><span>Limite para esta semana</span><strong>${money(d.weekly)}</strong></div><div class="row-head"><span>Essenciais ainda não cadastrados</span><strong>${money(d.essentials)}</strong></div><button class="btn secondary full" data-action="nav" data-tab="agenda">Abrir agenda de pagamentos</button><p class="help">O saldo em destaque é o saldo real informado. As despesas do período incluem meus compromissos identificados; faturas compartilhadas ficam indicadas separadamente. O livre para gastar considera o caixa, todas as pessoas, parcelas futuras e provisões.</p><h3>Saldo no tempo</h3>${chart(s)}<div class="benefits">${[['VR','Refeição'],['VA','Alimentação']].map(([id,label])=>`<div class="benefit"><span>${label}</span><strong>${money(s.settings.benefits[id])}</strong></div>`).join('')}</div><p class="help">Benefícios separados da conta. Entradas sem confirmação não liberam limite.</p></details><p class="local-footnote">${icon('shield')} Salvo neste aparelho · versão 2.3.0 · faça seu backup.</p>`;
}
const categoryMeta=value=>({
 'Alimentação':['food','#f59e0b'],'Mercado':['food','#f59e0b'],'Transporte':['car','#3b82f6'],'Combustível':['car','#3b82f6'],'Saúde':['heart','#f43f5e'],'Moradia':['home','#6366f1'],'Casa':['home','#6366f1'],'Lazer':['gift','#a855f7'],'Educação':['list','#14b8a6'],'Escola':['list','#14b8a6'],'Renda':['wallet','#10b981'],'Reembolso':['users','#bf5af2']
}[value]||['wallet','#8e8e93']);
function transactionCard(t){
 const receivable=tab==='history'?(payingSelection?paymentCandidates.get(t.id):receivingSelection?receiptsForRows(state(),[t])[0]:null):null;
 const [symbol,color]=categoryMeta(t.category),receipt=t.reimbursementId?state().events.find(e=>e.id===t.reimbursementId):null,paid=['paid','covered'].includes(receipt?.status),amount=t.displayAmount??(t.isSplit?t.myAmount:t.amount),person=t.isSplit?t.split.person:t.person||'JEFFERSON';
 return `<article class="transaction-card ${receivable&&receiptSelection.has(receivable.id)?`receipt-selected ${payingSelection?'payment-selected':''}`:''}">${receivable?`<label class="receipt-pick ${payingSelection?'payment-pick':''}"><input type="checkbox" data-action="select-receipt" data-id="${h(receivable.id)}" aria-label="Selecionar ${payingSelection?'pagamento':'recebimento'} ${h(receivable.description)}" ${receiptSelection.has(receivable.id)?'checked':''}><span>${payingSelection?(receivable.item?'Item da fatura de '+receivable.paymentMonth.slice(5)+'/'+receivable.paymentMonth.slice(0,4):t.isSplit?'Pagamento total da parcela':'Despesa pendente'):t.type==='income'?'Entrada pendente':'Reembolso total da compra'}<strong>${money(receivable.amount)}</strong></span></label>`:''}<button class="transaction-main" data-action="transaction" data-id="${h(t.id)}"><span class="category-icon" style="--category-color:${color}">${icon(symbol)}</span><span class="transaction-body"><strong>${h(t.description)} <span class="bank-tag">${h(t.bank)}</span></strong><small>${h(t.category)} · ${h(t.paymentMethod||t.payment)}${t.origin==='event'&&t.status==='deferred'?' · Adiado':t.origin==='event'&&t.type==='income'&&!t.confirmed&&t.status==='planned'?' · Não confirmado':t.origin==='event'&&t.status==='planned'?' · Previsto':''}</small></span><span class="transaction-amount ${t.type==='income'?'positive':''}"><b>${t.type==='income'?'+':'−'} ${money(amount)}</b><small>${t.date?dateText(t.date):t.origin==='event'?'Sem data':t.origin==='source-projection'?'Previsto · '+t.month.slice(5)+'/'+t.month.slice(0,4):h(t.month||historyMonth)}</small></span></button>${installmentBadge(t)}${['paid','covered'].includes(t.status)?`<span class="received-badge">${icon('check')} ${t.status==='covered'?'Já incluído no saldo':t.type==='income'?'Recebido':'Pago'}${t.paidDate?' em '+dateText(t.paidDate):''}</span>`:''}${t.isSplit?`<div class="split-banner"><span>Dividido com <b>${h(person)}</b></span><span>Total: ${money(t.amount)}</span>${receipt?`<button class="split-status ${paid?'paid':''}" data-action="toggle-reimbursement" data-id="${h(receipt.id)}" aria-label="${paid?'Reabrir':'Marcar recebido'} reembolso de ${h(person)}">${paid?'✓ Pago':'◷ Pendente'}</button>`:''}</div>`:person!=='JEFFERSON'?`<div class="owner-banner">${icon('users')} ${h(person)}${t.type==='income'?' · entrada':' · despesa desta pessoa'}</div>`:''}</article>`;
}
function installmentBadge(row){
 const info=installmentDetails(state(),row);if(!info)return '';
 if(info.grouped)return `<div class="installment-line"><span class="installment-pill grouped">${row.kind==='installments'?'Parcelas agrupadas · conferir fatura':'Parcelamento · conferir parcela'}</span></div>`;
 const status=info.settled?'Paga':info.deferred?'Adiada':info.unknown?'Conferir pagamento':'A pagar';
 return `<div class="installment-line"><span class="installment-pill ${info.settled?'paid':info.deferred?'deferred':''}">${icon('calendar')} Parcela ${info.part} de ${info.parts} <i>·</i> ${status}</span></div>`;
}
function transactionRows(){return ledgerForMonth(state(),historyMonth,{type:transactionType,category:transactionCategory,person:transactionPerson,search:historySearch});}
function renderReceiptSelection(action,id){
 const container=document.querySelector('#app-viewport'),position=container?.scrollTop||0;render();document.querySelector('#app-viewport').scrollTop=position;
 if(action){const input=[...document.querySelectorAll('input[data-action]')].find(el=>el.dataset.action===action&&(!id||el.dataset.id===id));input?.focus({preventScroll:true});}
}
function selectionEntries(rows){return payingSelection?paymentsForRows(state(),rows):receiptsForRows(state(),rows);}
function receiptBatchBar(eligible,chosen){
 const total=chosen.reduce((n,e)=>n+e.amount,0),all=eligible.length>0&&chosen.length===eligible.length;
 const expense=payingSelection;
 return `<section class="receipt-batch ${expense?'payment-batch':''}" aria-label="${expense?'Despesas selecionadas':'Recebimentos selecionados'}"><div class="receipt-batch-top"><label class="receipt-select-all"><input type="checkbox" data-action="select-visible-receipts" aria-label="Selecionar todas as ${expense?'despesas':'entradas'} pendentes desta consulta" ${all?'checked':''} ${eligible.length?'':'disabled'}><span>Selecionar todas <small>${eligible.length} ${expense?'despesa(s)':'entrada(s)'} pendente(s) nesta consulta</small></span></label><button class="textbtn" data-action="cancel-selection">Cancelar</button></div><div class="receipt-batch-actions"><div role="status" aria-live="polite"><small>${chosen.length} selecionado(s)</small><strong>${money(total)}</strong></div><button class="btn receive-now" data-action="${expense?'pay-selected':'receive-selected'}" ${chosen.length?'':'disabled'}>${icon('check')} ${expense?'Paguei agora':'Recebi agora'}</button></div><p>${eligible.length?expense?'Desconta somente os itens marcados do saldo de hoje. Nos cartões, abate a fatura correspondente; o restante continua pendente na Agenda.':'Registra o total no saldo de hoje. Cada recebimento é contado uma única vez.':expense?'Nenhuma despesa pendente com pagamento vinculado nesta consulta. Pix e benefícios já saem no lançamento; confira outros itens na Agenda.':'Nenhuma entrada pendente nesta seleção. Use o filtro Receitas ou escolha outro mês.'}</p></section>`;
}

function chart(s){const until=monthDate(todayBR(),3),p=dashboard(s,todayBR(),until).daily;if(p.length<2)return '<p class="empty">Cadastre movimentos para ver a projeção.</p>';const start=new Date(todayBR()+'T12:00:00Z').getTime(),end=new Date(until+'T12:00:00Z').getTime(),values=p.map(v=>v.balance),min=Math.min(0,...values),max=Math.max(100,...values),y=n=>140-(n-min)/(max-min)*115,x=date=>12+(new Date(date+'T12:00:00Z').getTime()-start)/(end-start)*330;let points=`12,${y(p[0].balance)}`;for(let i=1;i<p.length;i++)points+=` ${x(p[i].date)},${y(p[i-1].balance)} ${x(p[i].date)},${y(p[i].balance)}`;return `<svg class="chart" viewBox="0 0 355 170" role="img" aria-label="Projeção parcial do saldo nos próximos 90 dias"><line x1="12" y1="${y(0)}" x2="342" y2="${y(0)}" stroke="#3a3a3c" stroke-dasharray="4 4"/><polyline points="${points}" fill="none" stroke="#64d2ff" stroke-width="2.5"/><text x="12" y="163">${dateText(todayBR())}</text><text x="290" y="163">${dateText(until)}</text><text x="12" y="14">${h(money(max))}</text></svg>`;}
function agenda(){
 const list=agendaForMonth(state(),filterMonth,statusFilter,agendaPerson);
 return `<div class="page-head"><div><h1>Agenda do dinheiro</h1><p class="muted">O que entra, o que sai e em qual dia.</p></div></div><div class="toolbar">
 <label>Mês<input id="agenda-month" type="month" value="${filterMonth}" aria-label="Mês da agenda"></label>
 <label>Pessoa<select id="agenda-person" aria-label="Pessoa da agenda">${personOptions(agendaPerson,true)}</select></label>
 <label>Situação<select id="agenda-status" aria-label="Situação dos compromissos"><option value="open" ${statusFilter==='open'?'selected':''}>A pagar e receber</option><option value="deferred" ${statusFilter==='deferred'?'selected':''}>Dívidas adiadas</option><option value="closed" ${statusFilter==='closed'?'selected':''}>Conciliados e cancelados</option></select></label>
 <button class="btn secondary" data-action="new-event">${icon('plus')} Conta ou entrada</button></div>
 <p class="help">O filtro muda somente esta consulta. O disponível da conta considera todas as pessoas. Faturas com despesas de mais de uma pessoa ficam em Compartilhado.</p>
 <div class="notice">${icon('alert')}<div>Confira faturas e datas estimadas. Contas já refletidas no saldo podem ser marcadas como “Já incluído no saldo”.</div></div>
 <section class="card">${list.length?list.map(eventRow).join(''):'<p class="empty">Nenhum movimento nesta seleção.</p>'}</section><p class="footer-note">Saídas sem data ficam reservadas e aparecem em todos os meses. Parcelas novas aparecem nos respectivos vencimentos até a última.</p>`;
}
function history(){
 const s=state(),rows=transactionRows(),categories=[...new Set(ledgerForMonth(s,historyMonth).map(r=>r.category))].sort((a,b)=>a.localeCompare(b));
 const eligible=selectionEntries(rows),allowed=new Set(eligible.map(e=>e.id));for(const id of receiptSelection)if(!allowed.has(id))receiptSelection.delete(id);const chosen=eligible.filter(e=>receiptSelection.has(e.id));paymentCandidates=new Map(eligible.map(e=>[e.id,e]));
 return `<div class="page-head"><div><h1>Transações</h1><p class="muted">Filtre por tipo, categoria ou pessoa com quem dividiu</p></div></div><div class="receipts-toolbar batch-toolbar"><button class="btn secondary" data-action="toggle-receipt-selection">${receivingSelection?'Cancelar seleção':'Selecionar recebimentos'}</button><button class="btn secondary" data-action="toggle-payment-selection">${payingSelection?'Cancelar seleção':'Selecionar despesas'}</button></div><div class="search-field">${icon('search')}<input id="history-search" placeholder="Buscar por descrição, banco, pessoa..." aria-label="Buscar transações" value="${h(historySearch)}"></div>
 <div class="segmented">${[['all','Todas'],['expense','Despesas'],['income','Receitas']].map(([value,label])=>`<button data-action="transaction-type" data-value="${value}" class="${transactionType===value?'selected':''}" aria-pressed="${transactionType===value}">${label}</button>`).join('')}</div>
 <div class="transaction-filters"><div class="form-grid"><label>Mês<input id="history-month" type="month" aria-label="Mês das transações" value="${historyMonth}"></label><label>Filtrar por categoria<select id="filter-category" aria-label="Filtrar por categoria">${['ALL',...categories].map(c=>`<option value="${h(c)}" ${transactionCategory===c?'selected':''}>${c==='ALL'?'Todas as categorias':h(c)}</option>`).join('')}</select></label></div><label class="purple-label">Filtrar por pessoa / divisão<select id="filter-person" aria-label="Filtrar por pessoa / divisão"><option value="Todos" ${transactionPerson==='Todos'?'selected':''}>Todas as transações</option><option value="SINGLE_ONLY" ${transactionPerson==='SINGLE_ONLY'?'selected':''}>Apenas minhas (não divididas)</option><option value="DIVIDED_ALL" ${transactionPerson==='DIVIDED_ALL'?'selected':''}>Apenas divididas (todas)</option>${[...allPeople(),'Compartilhado'].map(p=>`<option value="${h(p)}" ${transactionPerson===p?'selected':''}>${h(p)}</option>`).join('')}</select></label></div>
 <div class="row-head results-header"><span class="small muted">${rows.length} ${rows.length===1?'transação':'transações'}</span><button class="textbtn" data-action="nav" data-tab="agenda">Agenda de pagamentos →</button></div>${receivingSelection||payingSelection?receiptBatchBar(eligible,chosen):''}<div class="transaction-list">${rows.map(transactionCard).join('')||'<p class="empty">Nenhuma transação encontrada com estes filtros.</p>'}</div><p class="help">Parcelas no mês do vencimento; planilha na competência original. Cada compra e acordo da planilha continua separado até a última parcela, a partir da última competência. Faturas completas e repasses ficam na Agenda; o pagamento da fatura não cria outra compra.</p>`;
}
function analytics(){
 const rows=ledgerForMonth(state(),historyMonth,{type:'expense',person:analyticsMode==='person'?'Todos':homePerson}).filter(r=>!['VR','VA'].includes(r.payment));let groups;
 if(analyticsMode==='category')groups=groupExpenses(rows.map(r=>({...r,amount:r.displayAmount,originalAmount:r.isSplit?undefined:r.originalAmount})));
 else if(analyticsMode==='bank')groups=groupExpenses(rows.filter(r=>cardsForState(state()).some(c=>c.id===r.payment)||r.bankId).map(r=>({...r,amount:r.displayAmount,originalAmount:r.isSplit?undefined:r.originalAmount,category:r.bank})));
 else groups=groupExpenses(rows.flatMap(r=>Object.entries(r.shares).map(([person,amount])=>({category:person,amount,originalAmount:!r.isSplit?r.originalAmount:undefined}))));
 const total=groups.reduce((n,g)=>n+g.amount,0),title=analyticsMode==='category'?'Gastos por categoria':analyticsMode==='bank'?'Gastos por cartão / banco':'Despesas por pessoa',positive=groups.filter(g=>g.amount>0),circle=2*Math.PI*72;let offset=0;
 const arcs=positive.map((g,i)=>{const size=g.amount/positive.reduce((n,v)=>n+v.amount,0)*circle,result=`<circle cx="110" cy="110" r="72" fill="none" stroke="${chartColors[i%chartColors.length]}" stroke-width="32" stroke-dasharray="${size} ${circle-size}" stroke-dashoffset="${-offset}" transform="rotate(-90 110 110)"><title>${h(g.category)}: ${money(g.amount)}</title></circle>`;offset+=size;return result;}).join('');
 return `<div class="page-head"><div><h1>Análise e divisões</h1><p class="muted">Distribuição de gastos e valores divididos</p></div></div><div class="segmented">${[['category','Categoria'],['bank','Cartão/Banco'],['person','Por pessoa']].map(([value,label])=>`<button data-action="analytics-mode" data-value="${value}" class="${analyticsMode===value?'selected':''}" aria-pressed="${analyticsMode===value}">${label}</button>`).join('')}</div><div class="analysis-filters form-grid"><label>Mês<input type="month" id="home-month" aria-label="Mês da análise" value="${historyMonth}"></label>${analyticsMode!=='person'?`<label>Pessoa<select id="home-person" aria-label="Pessoa da análise">${personOptions(homePerson,true)}</select></label>`:''}</div>
 <section class="card analysis-chart"><h2 class="eyebrow">${title}</h2><svg viewBox="0 0 220 220" class="analysis-donut" role="img" aria-label="${title}. Total: ${money(total)}"><circle cx="110" cy="110" r="72" fill="none" stroke="#3a3a3c" stroke-width="32"/>${arcs}<text x="110" y="105" text-anchor="middle" class="donut-label">Total</text><text x="110" y="126" text-anchor="middle" class="donut-total">${money(total)}</text></svg></section>
 <section class="card analysis-breakdown"><h2 class="eyebrow">Detalhamento</h2>${groups.map((g,i)=>`<div class="breakdown-item"><div class="row-head"><span><i style="background:${chartColors[i%chartColors.length]}"></i>${h(g.category)}</span><b>${money(g.amount)}</b></div><div class="bar"><i style="width:${total>0?Math.max(0,g.amount/total*100):0}%;background:${chartColors[i%chartColors.length]}"></i></div><small>${total>0?(g.amount/total*100).toLocaleString('pt-BR',{maximumFractionDigits:1}):0}% do total</small></div>`).join('')||'<p class="empty">Nenhuma despesa neste período.</p>'}</section><p class="help">Benefícios separados. Por pessoa considera a parte de cada participante; o limite para gastar continua considerando todos os compromissos.</p>`;
}
function transactionDetail(id){
 const t=ledgerForMonth(state(),historyMonth).find(r=>r.id===id);if(!t)return;
 if(t.eventId){eventModal(t.eventId);return;}
 if(t.paymentEventId&&state().events.find(e=>e.id===t.paymentEventId)?.kind==='fixed'){eventModal(t.paymentEventId);return;}
 modal('Detalhe da transação',`<h3>${h(t.description)}</h3><p class="detail-value">${money(t.amount)}</p><p class="muted">${h(t.category)} · ${h(t.bank)} · ${h(t.person||'JEFFERSON')}</p>${t.part?`<p>Parcela ${t.part}/${t.parts} · ${t.origin==='source-projection'?'competência '+monthName(t.month):'vencimento '+dateText(t.date)}</p>`:''}${t.isSplit?`<div class="split-calculation"><div>Minha parte<strong>${money(t.myAmount)}</strong></div><div>${h(t.split.person)}<strong>${money(t.amount-t.myAmount)}</strong></div></div>`:''}${['source','source-projection'].includes(t.origin)?`<p class="help">${t.origin==='source-projection'?'Parcela prevista a partir da última competência da planilha. Confira a cobrança real; o pagamento da fatura é conciliado na Agenda.':'Registro preservado da planilha original.'}</p>${t.paymentEventId?`<button class="btn secondary full" data-action="event" data-id="${h(t.paymentEventId)}">Ver pagamento na Agenda</button>`:''}`:`<button class="btn danger full" data-action="undo-purchase" data-id="${h(t.purchaseId)}">Desfazer compra${t.parts>1?' (todas as parcelas)':''}</button>`}`);
}
function settings(){const s=state();return `<div class="settings-layout"><div class="page-head"><div><h1>Ajustes</h1><p class="muted">Configurações e gerenciamento</p></div></div><section class="card profile-card"><div class="profile-avatar"><span>J</span></div><div><strong>Jefferson</strong><p>Controle local · sem conta vinculada</p></div></section><button class="settings-link" data-action="nav" data-tab="agenda">${icon('calendar')} Agenda de pagamentos ${icon('arrow')}</button>${cardSettings()}<form id="settings-form"><section class="card"><h2>Saldo e limite seguro</h2><div class="form-grid"><div class="field"><label for="balance">Saldo real da conta (R$)</label><input id="balance" name="balance" inputmode="decimal" required value="${currencyInput(s.settings.balance)}"></div><div class="field"><label for="asOf">Saldo conferido em</label><input id="asOf" name="asOf" type="date" required value="${s.settings.asOf}"></div><div class="field"><label for="essentials">Essenciais até o próximo salário (R$)</label><input id="essentials" name="essentials" inputmode="decimal" placeholder="Informe 0 se já cadastrou tudo" value="${currencyInput(s.settings.essentials)}"></div><div class="field"><label for="safety">Margem de segurança (R$)</label><input id="safety" name="safety" inputmode="decimal" required value="${currencyInput(s.settings.safety)}"></div></div><p class="help">Provisione somente gastos essenciais ainda não incluídos na Agenda: combustível, transporte, saúde e outros. Contas já previstas não entram outra vez. Use saldo sem o limite do LIS.</p><div class="field"><label for="monthlyLimit">Teto opcional para novas compras de desejos neste mês (R$)</label><input id="monthlyLimit" name="monthlyLimit" inputmode="decimal" placeholder="Em branco: usar somente o caixa disponível" value="${currencyInput(s.settings.monthlyLimit)}"><p class="help">Aplica-se aos novos gastos registrados no aplicativo; não é uma autorização para ultrapassar o caixa disponível.</p></div><label class="check"><input type="checkbox" name="reconciled" ${s.settings.reconciled?'checked':''}><span>Conferi o saldo e a Agenda, identifiquei o que já está pago e revisei as datas e valores necessários. Entendo que a projeção só inclui o que foi cadastrado.</span></label></section><section class="card"><h2>Benefícios</h2><div class="form-grid">${[['VR','Vale-refeição'],['VA','Vale-alimentação']].map(([id,label])=>`<div class="field"><label for="benefit-${id}">${label} · saldo atual</label><input id="benefit-${id}" name="benefit-${id}" inputmode="decimal" placeholder="Não informado" value="${currencyInput(s.settings.benefits[id])}"></div>`).join('')}</div><p class="help">Atualize estes saldos quando o benefício for creditado. Valores não se somam ao dinheiro em conta.</p></section><p class="form-error" id="settings-error" role="alert"></p><button class="btn" type="submit">${icon('check')} Salvar ajustes neste aparelho</button></form><section class="card" style="margin-top:22px"><h2>Seu backup, em arquivo</h2><p class="small muted">Os registros ficam no armazenamento deste navegador ou app instalado. Limpar os dados do Safari, usar modo privado, trocar de aparelho ou mudar o endereço do aplicativo pode impedir o acesso aos registros locais.</p><button class="btn" data-action="backup">${icon('download')} Exportar backup JSON</button><button class="btn secondary" data-action="csv">Exportar lançamentos CSV</button><button class="btn ghost" data-action="import">Importar backup</button><button class="textbtn" data-action="recover">Recuperar versão local anterior</button><p class="help">JSON guarda o controle completo. CSV serve para consultar despesas em uma planilha. Salve o backup em Arquivos; ele contém seus dados financeiros.</p></section><section class="card"><h2>No iPhone</h2><ol class="small muted"><li>Abra o endereço no Safari.</li><li>Compartilhar → Adicionar à Tela de Início.</li><li>Abra o aplicativo pelo novo ícone.</li><li>Importe o arquivo inicial ou seu último backup.</li><li>Depois do primeiro carregamento completo, o aplicativo pode funcionar sem internet.</li></ol><p class="help">Instalação e armazenamento podem ser separados do Safari. Importe o backup no local em que vai usar o controle. O código não contém rastreamento nem envio dos seus registros.</p></section><section class="card"><h2>Fontes e premissas do seu controle</h2>${s.sources.map(r=>`<p class="small"><strong>${h(r.name)}</strong><br><span class="muted">${h(r.note)}</span></p>`).join('')||'<p class="small muted">Controle iniciado vazio.</p>'}<p class="help">Entradas extras e 13º permanecem separados do salário recorrente. O auxílio-creche termina na data cadastrada nas previsões importadas. Cada compromisso pode ser editado na Agenda.</p></section></div>`;}
function modal(title,body){
 const transaction=title==='Nova Transação';
 document.querySelector('#modal-root').innerHTML=`<div class="sheet-overlay"><section class="sheet" role="dialog" aria-modal="true" aria-label="${h(title)}"><div class="sheet-head ${transaction?'transaction-sheet-head':''}">${transaction?'<button class="textbtn" data-action="close">Cancelar</button>':''}<h2>${h(title)}</h2>${transaction?'<button class="textbtn" type="submit" form="purchase-form">Salvar</button>':'<button class="close" data-action="close" aria-label="Fechar">×</button>'}</div>${body}</section></div>`;
 document.body.style.overflow='hidden';
}
function closeModal(){pendingImport=null;pendingEventEdit=null;document.querySelector('#modal-root').innerHTML='';document.body.style.overflow='';}
function purchaseModal(){
 modalType='expense';const cards=cardsForState(state());
 modal('Nova Transação',`<form id="purchase-form" data-type="expense"><div class="segmented modal-type"><button type="button" data-action="modal-type" data-value="expense" class="expense selected" aria-pressed="true">Despesa</button><button type="button" data-action="modal-type" data-value="income" class="income" aria-pressed="false">Receita</button></div>
 <div class="amount-field"><label for="purchase-amount">Valor total</label><div><span>R$</span><input id="purchase-amount" name="amount" inputmode="decimal" placeholder="0,00" required autocomplete="off" aria-label="Valor total"></div></div>
 <div class="field"><label for="purchase-description">Descrição</label><input id="purchase-description" name="description" placeholder="Ex: Pizza, presente, mercado..." maxlength="300" required></div>
 <div id="expense-fields"><div class="form-grid"><div class="field"><label for="purchase-category">Categoria</label><select id="purchase-category" name="category">${['Alimentação','Transporte','Saúde','Moradia','Lazer','Educação','Mercado','Combustível','Vestuário','Assinaturas','Escola','Outros'].map(c=>`<option>${c}</option>`).join('')}</select></div><div class="field"><label for="purchase-method">Forma de pagamento</label><select id="purchase-method" name="method">${['Pix','Cartão de Crédito','Cartão de Débito','Dinheiro','Transferência','VR','VA'].map(c=>`<option>${c}</option>`).join('')}</select><input type="hidden" id="purchase-payment" name="payment" value="Pix"></div></div>
 <div id="bank-select-container" class="field" hidden><label for="purchase-bank" class="blue-label">Selecione o cartão / banco</label><select id="purchase-bank" name="bank">${cards.map(c=>`<option value="${h(c.id)}">${h(c.name)}</option>`).join('')}</select><button type="button" class="textbtn" data-action="card-settings">Cadastrar ou editar cartão em Ajustes</button></div>
 <div id="credit-fields" hidden><div class="field"><label for="purchase-installments">Parcelas</label><input id="purchase-installments" name="installments" type="number" min="1" max="60" value="1" inputmode="numeric"></div><p class="help" id="purchase-card-info"></p></div>
 <label class="split-toggle" for="toggle-split"><span class="split-toggle-icon">${icon('users')}</span><span><strong>Dividir esta despesa?</strong><small>Racha com outra pessoa / amigo</small></span><input type="checkbox" id="toggle-split" aria-label="Dividir esta despesa?"></label>
 <div id="split-fields-panel" hidden><div class="field"><label for="input-split-person">Com quem vai dividir?</label><input id="input-split-person" name="splitPerson" placeholder="Ex: Camila, Fatima..." maxlength="80" list="split-people"><datalist id="split-people">${allPeople().filter(p=>p!=='JEFFERSON').map(p=>`<option value="${h(p)}">`).join('')}</datalist></div><div class="form-grid"><div class="field"><label for="input-split-percent">Minha parte (%)</label><select id="input-split-percent" name="splitPercent">${[[50,'50% (metade cada)'],[33.33,'33,33% (por 3)'],[25,'25% (por 4)'],[60,'60%'],[40,'40%'],[0,'0% (só a outra pessoa)'],[100,'100% (toda minha)']].map(([v,label])=>`<option value="${v}">${label}</option>`).join('')}</select></div><div class="field"><label for="input-split-status">Status da cobrança</label><select id="input-split-status" name="splitStatus"><option>Pendente</option><option>Pago</option></select></div></div><div class="split-calculation"><div>Sua parte<strong id="my-share-calculated">R$ 0,00</strong></div><div>A receber da pessoa<strong id="other-share-calculated">R$ 0,00</strong></div></div><p class="help">“Pago” significa que o reembolso já entrou na conta e será somado ao saldo.</p></div>
 <div class="field" id="owner-field"><label for="purchase-person">Despesa de</label><select id="purchase-person" name="person">${allPeople().map(p=>`<option>${h(p)}</option>`).join('')}</select></div></div>
 <div id="income-fields" hidden><label class="check"><input type="checkbox" name="incomeReceived" checked><span>Já recebi · incluir no saldo da conta</span></label><p class="help">Desmarque para cadastrar uma receita prevista, sem alterar o saldo atual.</p></div>
 <div class="field"><label for="purchase-date">Data</label><input id="purchase-date" name="date" type="date" required value="${todayBR()}"></div><details id="purchase-options"><summary>Finalidade e data do reembolso</summary><div class="form-grid"><div class="field"><label for="purchase-budget">Finalidade</label><select id="purchase-budget" name="budget"><option>Desejos</option><option>Essencial</option></select></div><div class="field"><label for="purchase-reimbursement">Reembolso previsto</label><input id="purchase-reimbursement" name="reimbursementDate" type="date"></div></div></details><div class="purchase-preview" id="purchase-preview">Informe o valor para ver o efeito no disponível.</div><p class="form-error" id="purchase-error" role="alert"></p><button class="btn full" type="submit">Adicionar Transação</button></form>`);
}
function reviewImport(payload,name){
 const report=inspectBackup(payload);pendingImport=report;
 const current=doc?.state.purchases.filter(p=>!p.void).length||0;
 modal('Conferir importação',`<p class="small muted">${h(name)}</p><div class="import-report"><div class="row-head"><span>Registros da planilha</span><strong>${report.historyCount}</strong></div><div class="row-head"><span>Compras lançadas no aplicativo</span><strong>${report.purchasesCount}</strong></div><div class="row-head"><span>Compromissos e previsões</span><strong>${report.eventsCount}</strong></div><div class="row-head"><span>Saldo salvo no arquivo</span><strong>${money(report.state.settings.balance)}</strong></div><div class="row-head"><span>Mês que será aberto</span><strong>${monthName(report.month)}</strong></div></div>${report.purchasesCount===0?'<p class="import-note">Este arquivo contém os registros da planilha e previsões, mas nenhuma compra nova lançada pelo aplicativo.</p>':''}${doc?`<p class="import-note">O controle atual tem ${current} compra(s) lançada(s). Importar substitui o controle atual; uma cópia dele ficará como versão local anterior.</p><button class="btn secondary full" data-action="backup">Exportar o controle atual antes</button>`:''}<p class="help">A importação preserva valores, datas e situações do arquivo. Confira o resumo antes de continuar.</p><button class="btn full" data-action="confirm-import">Confirmar importação</button><button class="textbtn full" data-action="close">Cancelar</button>`);
}

function eventModal(id,draft=null){
 const e=draft||(id?state().events.find(e=>e.id===id):{id:crypto.randomUUID(),description:'',amount:0,direction:'out',date:'',status:'planned',confirmed:true,account:'Conta',kind:'other',source:'manual',person:'JEFFERSON'});if(!e)return;
 const closed=['paid','covered','void'].includes(e.status),partial=itemPaidTotal(e)>0,locked=closed||partial,remaining=outstandingAmount(e),recurrence=id?recurrenceForEvent(state(),id):null;
 modal(id?'Detalhe do movimento':'Conta ou entrada',`<form id="event-form" data-id="${h(e.id)}">
 ${recurrence?'<p class="recurrence-note">Conta mensal recorrente. Ao mudar o valor e salvar, escolha se vale só para este mês ou também para os próximos.</p>':''}
 <div class="field"><label for="event-description">Descrição</label><input id="event-description" name="description" required maxlength="300" value="${h(e.description)}" ${locked?'readonly':''}></div>
 <div class="form-grid"><div class="field"><label for="event-amount">${partial&&!closed?'Restante a pagar':'Valor'} (R$)</label><input id="event-amount" name="amount" inputmode="decimal" required value="${e.amount?currencyInput(partial&&!closed?remaining:e.amount):''}" ${locked?'readonly':''}></div>
 <div class="field"><label for="event-date">Data de pagar ou receber</label><input id="event-date" name="date" type="date" value="${e.date}" ${locked?'readonly':''}></div>
 <div class="field"><label for="event-direction">Movimento</label><select id="event-direction" name="direction" ${locked?'disabled':''}><option value="out" ${e.direction==='out'?'selected':''}>Saída de dinheiro</option><option value="in" ${e.direction==='in'?'selected':''}>Entrada de dinheiro</option></select></div>
 <div class="field"><label for="event-person">Pessoa</label><select id="event-person" name="person" ${locked?'disabled':''}>${[...people,'Compartilhado'].map(p=>`<option ${(e.person||'JEFFERSON')===p?'selected':''}>${p}</option>`).join('')}</select></div>
 <div class="field"><label for="event-status">Situação</label><select id="event-status" name="status" ${locked?'disabled':''}><option value="planned" ${e.status==='planned'?'selected':''}>Previsto</option><option value="deferred" ${e.status==='deferred'?'selected':''}>Adiado · reservar valor</option><option value="void" ${e.status==='void'?'selected':''}>Cancelado</option></select></div></div>
 <p class="help">${h(e.note||'Valores e datas podem ser atualizados. Uma conta recebida ou paga pode ser conciliada abaixo.')}</p>
 ${partial?`<div class="notice"><div>Valor original: <strong>${money(e.amount)}</strong><br>Itens pagos: <strong>${money(itemPaidTotal(e))}</strong>${!closed?`<br>Restante: <strong>${money(remaining)}</strong>`:''}</div></div><details class="item-payments-detail"><summary>Ver itens pagos</summary>${e.itemPayments.map(p=>{const original=state().history.find(r=>p.key===r.id||p.key.startsWith('projection-'+r.id+'-'));return `<p>${h(original?.description||'Item da despesa')} · ${money(p.amount)} · ${dateText(p.paidDate)}</p>`;}).join('')}</details>`:''}
 ${closed?`<p class="notice">${e.status==='covered'?'Restante já incluído no saldo informado':e.status==='paid'?`Conciliado em ${dateText(e.paidDate)}`:'Movimento cancelado'}</p><button type="button" class="btn secondary full" data-action="restore-event" data-id="${h(e.id)}">Desfazer conciliação / reabrir</button>`:`${partial?'':`<label class="check"><input type="checkbox" name="confirmed" ${e.confirmed?'checked':''}><span>Valor e data confirmados. Entradas sem confirmação ficam fora do disponível.</span></label><p class="form-error" id="event-error" role="alert"></p><button class="btn full" type="submit">Salvar previsão</button>`}
 ${id?`<div class="form-grid" style="margin-top:13px"><button class="btn secondary" type="button" data-action="settle-event" data-id="${h(e.id)}">${e.direction==='in'?'Recebi agora':partial?'Pagar restante agora':'Paguei agora'}</button><button class="btn ghost" type="button" data-action="cover-event" data-id="${h(e.id)}">${partial?'Restante já incluído no saldo':'Já incluído no saldo'}</button></div><p class="help">${partial?'As ações acima conciliam somente o restante. Para editar a previsão, reabra os pagamentos dos itens abaixo.':'“Agora” altera o saldo pelo valor salvo. “Já incluído” concilia sem alterar o saldo. Para valor diferente, salve a previsão antes.'}</p>`:''}
 ${partial?`<button type="button" class="btn ghost full" data-action="restore-event" data-id="${h(e.id)}">Reabrir todos os pagamentos dos itens</button><p class="help">Devolve ${money(-(e.applied||0))} ao saldo do controle e deixa todos os itens desta fatura pendentes novamente.</p>`:''}`}</form>`);
}

function reviewRecurringEdit(input){
 const old=state().events.find(e=>e.id===input.id),series=recurrenceForEvent(state(),input.id);if(!old||!series)throw new Error('Recorrência não encontrada. Abra a conta novamente.');
 pendingEventEdit={input:clone(input),revision:doc.revision};
 modal('Onde alterar o valor?',`<p class="small muted">${h(old.description)}</p><div class="recurrence-change"><span>${money(old.amount)}</span>${icon('arrow')}<strong>${money(input.amount)}</strong></div><p>Escolha como aplicar o novo valor.</p>
 <button class="scope-option" data-action="save-event-scope" data-scope="single"><strong>Só este mês</strong><small>Altera somente ${h(monthName(series.month))}. Os próximos meses mantêm seus valores.</small></button>
 <button class="scope-option" data-action="save-event-scope" data-scope="future"><strong>Este mês e os próximos</strong><small>Aplica ${money(input.amount)} a ${series.targets.length} ocorrência(s) pendente(s) cadastrada(s), de ${h(monthName(series.month))} até ${h(monthName(series.lastMonth))}.</small></button>
 <p class="help">Meses anteriores, pagos e cancelados são preservados. Nas próximas ocorrências, será alterado apenas o valor. O saldo atual só muda quando você registrar o pagamento.</p><p class="form-error" id="recurrence-error" role="alert"></p><button class="textbtn full" data-action="back-event-edit">Voltar para editar</button>`);
}

async function exportFile(name,content,type){const blob=new Blob([content],{type}),file=new File([blob],name,{type});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'Backup do meu controle'});return;}catch(e){if(e.name==='AbortError')return;}}
 const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);notify('Arquivo preparado. Salve-o em Arquivos.');}
async function exportCSV(){
 const cell=v=>{let x=String(v??'');if(/^[=+@-]/.test(x))x="'"+x;return '"'+x.replace(/"/g,'""')+'"';};
 const rows=[['Origem','Data / competência','Pessoa','Descrição','Categoria','Pagamento','Valor (R$)','Dividido com','Minha parte (R$)','Parte da pessoa (R$)']];
 for(const r of state().history)rows.push(['Planilha',r.month,r.person,r.description,r.category,paymentName(state(),r.account),String(r.originalAmount??r.amount/100).replace('.',',')]);
 for(const r of state().purchases.filter(p=>!p.void))rows.push(['Aplicativo',r.date,r.person,r.description,r.category,paymentName(state(),r.bankId||r.payment),currencyInput(r.amount),r.split?.person||'',r.split?currencyInput(r.split.myAmount):'',r.split?currencyInput(r.split.otherAmount):'']);
 await exportFile('meus-gastos-'+todayBR()+'.csv','\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8');
}
document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;try{
 if(action==='nav'){if(b.dataset.tab==='new')purchaseModal();else{if(b.dataset.tab!=='history'){receivingSelection=false;payingSelection=false;receiptSelection.clear();}tab=b.dataset.tab;render();document.querySelector('#app-viewport').scrollTo({top:0,behavior:'instant'});}}
 else if(['toggle-receipt-selection','toggle-payment-selection','cancel-selection'].includes(action)){
   const receipt=action==='toggle-receipt-selection',payment=action==='toggle-payment-selection';
   receivingSelection=receipt&&!receivingSelection;payingSelection=payment&&!payingSelection;receiptSelection.clear();renderReceiptSelection();
   if(receivingSelection||payingSelection)document.querySelector('.receipt-batch')?.scrollIntoView({block:'start',behavior:'instant'});
 }
 else if(action==='pay-selected'){
   if(busy||!payingSelection)return;
   const entries=paymentsForRows(state(),transactionRows()).filter(e=>receiptSelection.has(e.id)),total=entries.reduce((n,e)=>n+e.amount,0);
   if(!entries.length)throw new Error('Selecione pelo menos uma despesa pendente.');b.disabled=true;
   try{await persist(payExpenses(state(),entries.map(e=>e.id),historyMonth));payingSelection=false;receiptSelection.clear();renderReceiptSelection();notify(`${entries.length} despesa(s) paga(s). ${money(total)} descontado(s) do saldo.`);}finally{b.disabled=false;}
 }
 else if(action==='receive-selected'){
   if(busy||!receivingSelection)return;
   const entries=receiptsForRows(state(),transactionRows()).filter(e=>receiptSelection.has(e.id)),total=entries.reduce((n,e)=>n+e.amount,0);
   if(!entries.length)throw new Error('Selecione pelo menos uma entrada pendente.');b.disabled=true;
   try{await persist(receiveEvents(state(),entries.map(e=>e.id)));receivingSelection=false;payingSelection=false;receiptSelection.clear();renderReceiptSelection();notify(`${entries.length} recebimento(s) registrado(s). ${money(total)} adicionado(s) ao saldo.`);}finally{b.disabled=false;}
 }
 else if(action==='transaction-type'){transactionType=b.dataset.value;render();}
 else if(action==='analytics-mode'){analyticsMode=b.dataset.value;render();}
 else if(action==='transaction')transactionDetail(b.dataset.id);
 else if(action==='toggle-reimbursement'){const e=state().events.find(e=>e.id===b.dataset.id);await persist(['paid','covered'].includes(e.status)?restoreEvent(state(),e.id):settleEvent(state(),e.id));notify('Reembolso atualizado no saldo.');}
 else if(action==='modal-type'){modalType=b.dataset.value;const form=document.querySelector('#purchase-form');form.dataset.type=modalType;form.querySelectorAll('[data-action="modal-type"]').forEach(el=>{const selected=el.dataset.value===modalType;el.classList.toggle('selected',selected);el.setAttribute('aria-pressed',String(selected));});document.querySelector('#purchase-options').hidden=modalType==='income';updatePaymentFields();updatePurchasePreview();}
 else if(action==='purchase')purchaseModal();else if(action==='close')closeModal();else if(action==='event')eventModal(b.dataset.id);else if(action==='new-event')eventModal();
 else if(action==='save-event-scope'){
   if(busy||!pendingEventEdit)return;const pending=pendingEventEdit;
   if(pending.revision!==doc.revision)throw new Error('O controle mudou. Abra a conta novamente antes de alterar.');
   const buttons=[...document.querySelectorAll('[data-action="save-event-scope"]')];buttons.forEach(el=>el.disabled=true);
   try{await persist(editEvent(state(),pending.input,b.dataset.scope));closeModal();notify(b.dataset.scope==='future'?'Valor atualizado neste mês e nas próximas ocorrências pendentes.':'Valor atualizado somente neste mês.');}
   catch(e){const error=document.querySelector('#recurrence-error');if(error)error.textContent=e.message;else notify(e.message,true);}
   finally{buttons.forEach(el=>el.disabled=false);}
 }
 else if(action==='back-event-edit'){if(!pendingEventEdit)return;const input=pendingEventEdit.input;pendingEventEdit=null;eventModal(input.id,input);}
 else if(action==='new-card')cardModal();else if(action==='edit-card')cardModal(b.dataset.id);else if(action==='card-settings'){closeModal();tab='settings';render();document.querySelector('#cards-settings').scrollIntoView({block:'start'});}
 else if(action==='chip'){document.querySelector('#purchase-description').value=b.dataset.description;document.querySelector('#purchase-category').value=b.dataset.category;document.querySelector('#purchase-description').dispatchEvent(new Event('input',{bubbles:true}));}
 else if(action==='import')document.querySelector('#import-file').click();
 else if(action==='confirm-import'){
   if(!pendingImport)throw new Error('Escolha o arquivo novamente.');const report=pendingImport;b.disabled=true;
   try{await persist(report.state);historyMonth=report.month;filterMonth=report.month;transactionType='all';transactionCategory='ALL';transactionPerson='Todos';historySearch='';receivingSelection=false;payingSelection=false;receiptSelection.clear();homePerson='JEFFERSON';agendaPerson='Todos';statusFilter='open';tab='home';render();closeModal();notify(`Importado: ${report.historyCount} registros da planilha e ${report.purchasesCount} compras novas.`);navigator.storage?.persist?.().catch(()=>{});}finally{b.disabled=false;}
 }
 else if(action==='blank'){await persist(blankState());notify('Controle vazio criado neste aparelho.');}
 else if(action==='settle-event'||action==='cover-event'){await persist(settleEvent(state(),b.dataset.id,todayBR(),action==='cover-event'));closeModal();notify('Movimento conciliado e salvo neste aparelho.');}
 else if(action==='restore-event'){const e=state().events.find(e=>e.id===b.dataset.id);let s;if(e.status==='void'){s=clone(state());s.events.find(x=>x.id===e.id).status='planned';}else s=restoreEvent(state(),e.id);await persist(s);closeModal();notify('Movimento reaberto.');}
 else if(action==='undo-purchase'){await persist(undoPurchase(state(),b.dataset.id));closeModal();notify('Lançamento desfeito.');}
 else if(action==='backup')await exportFile('meu-dinheiro-'+todayBR()+'.json',JSON.stringify({format:'meu-dinheiro-backup',exportedAt:new Date().toISOString(),state:state()},null,2),'application/json');
 else if(action==='csv')await exportCSV();
 else if(action==='recover'){const old=await previousControl();if(!old)throw new Error('Não há uma versão anterior neste aparelho.');if(confirm('Recuperar a versão local anterior? A versão atual ficará guardada como anterior.')){await persist(old.state);notify('Versão anterior recuperada.');}}
 }catch(e){notify(e.message,true);}});
document.addEventListener('change',ev=>{
 if(ev.target.dataset.action==='select-receipt'){const id=ev.target.dataset.id;if(ev.target.checked)receiptSelection.add(id);else receiptSelection.delete(id);renderReceiptSelection('select-receipt',id);return;}
 if(ev.target.dataset.action==='select-visible-receipts'){const entries=selectionEntries(transactionRows());receiptSelection.clear();if(ev.target.checked)for(const e of entries)receiptSelection.add(e.id);renderReceiptSelection('select-visible-receipts');return;}
if(ev.target.id==='home-month'){historyMonth=ev.target.value;render();}if(ev.target.id==='home-person'){homePerson=ev.target.value;render();}if(ev.target.id==='agenda-month'){filterMonth=ev.target.value;render();}if(ev.target.id==='agenda-person'){agendaPerson=ev.target.value;render();}if(ev.target.id==='agenda-status'){statusFilter=ev.target.value;render();}if(ev.target.id==='history-month'){historyMonth=ev.target.value;render();}if(ev.target.id==='filter-person'){transactionPerson=ev.target.value;render();}if(ev.target.id==='filter-category'){transactionCategory=ev.target.value;render();}if(ev.target.id==='history-search'){historySearch=ev.target.value;render();}if(ev.target.closest('#purchase-form')){updatePaymentFields();updatePurchasePreview();}});
function updatePurchasePreview(){
 const form=document.querySelector('#purchase-form');if(!form)return;const preview=form.querySelector('#purchase-preview');
 try{
   const p=purchaseInput(form,'preview'),percent=Number(form.querySelector('#input-split-percent').value),mine=Math.round(p.amount*percent/100);
   form.querySelector('#my-share-calculated').textContent=money(mine);form.querySelector('#other-share-calculated').textContent=money(p.amount-mine);
   if(modalType==='income'){preview.textContent=form.querySelector('[name=incomeReceived]').checked?`Saldo após receber: ${money(state().settings.balance+p.amount)}`:'Receita prevista: o saldo atual permanece igual.';return;}
   const s=addPurchase(state(),p),d=dashboard(s),parts=s.events.filter(e=>e.purchaseId==='preview'&&e.kind==='card');
   preview.textContent=(parts.length?`${parts.length} parcela(s) · primeira ${dateText(parts[0].date)} · última ${dateText(parts.at(-1).date)}. `:'')+`Livre após a transação: ${money(d.free)}.`;
 }catch(e){preview.textContent=e.message;}
}
document.addEventListener('input',ev=>{
 if(ev.target.closest('#purchase-form'))updatePurchasePreview();
 if(ev.target.id==='history-search'){historySearch=ev.target.value;const cursor=ev.target.selectionStart;const position=document.querySelector('#app-viewport').scrollTop;render();const field=document.querySelector('#history-search');field.focus();field.setSelectionRange(cursor,cursor);document.querySelector('#app-viewport').scrollTop=position;}
});
document.addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.target,button=form.querySelector('[type=submit]');if(!button||form.dataset.saving)return;form.dataset.saving='true';button.disabled=true;const error=form.querySelector('.form-error');if(error)error.textContent='';try{const f=Object.fromEntries(new FormData(form));
 if(form.id==='card-form'){const s=clone(state()),cards=cardsForState(s).map(c=>({...c})),card={id:form.dataset.id,name:f.name.trim(),dueDay:Number(f.dueDay),closingDay:Number(f.closingDay)},index=cards.findIndex(c=>c.id===card.id);if(index<0)cards.push(card);else cards[index]=card;s.settings.cards=cards;await persist(s);closeModal();notify('Cartão salvo. Próximas compras usarão este calendário.');}
 if(form.id==='purchase-form'){const id=crypto.randomUUID();if(modalType==='income'){await persist(addIncome(state(),{id,amount:parseMoney(f.amount),description:f.description,date:f.date,received:!!f.incomeReceived}));}else await persist(addPurchase(state(),purchaseInput(form,id)));closeModal();notify('Transação salva neste aparelho.');}
 if(form.id==='settings-form'){const s=clone(state());for(const key of ['balance','essentials','safety','monthlyLimit'])s.settings[key]=f[key]===''&&['essentials','monthlyLimit'].includes(key)?null:parseMoney(f[key]);s.settings.asOf=f.asOf;s.settings.reconciled=!!f.reconciled;for(const id of ['VR','VA'])s.settings.benefits[id]=f['benefit-'+id]===''?null:parseMoney(f['benefit-'+id]);await persist(s);notify('Ajustes salvos neste aparelho.');}
 if(form.id==='event-form'){
   const old=state().events.find(e=>e.id===form.dataset.id);
   const input={...(old||{id:form.dataset.id,source:'manual',kind:'other',account:'Conta',person:'JEFFERSON'}),person:f.person||old?.person||'JEFFERSON',description:f.description.trim(),amount:parseMoney(f.amount),date:f.date,direction:f.direction,status:f.status,confirmed:!!f.confirmed&&!!f.date,review:false};
   if(input.amount<=0)throw new Error('Informe um valor maior que zero.');
   if(input.direction==='in'&&input.status==='deferred')throw new Error('Use Previsto para uma entrada adiada.');
   if(old){
     if(input.amount!==old.amount&&input.direction==='out'&&input.status!=='void'&&recurrenceForEvent(state(),old.id)){reviewRecurringEdit(input);}
     else{await persist(editEvent(state(),input));closeModal();notify('Previsão salva.');}
   }else{const s=clone(state());s.events.push(input);await persist(s);closeModal();notify('Previsão salva.');}
 }
 }catch(e){if(error)error.textContent=e.message;else notify(e.message,true);}finally{button.disabled=false;delete form.dataset.saving;}});
document.querySelector('#import-file').addEventListener('change',async ev=>{try{const file=ev.target.files?.[0];if(!file)return;if(file.size>2000000)throw new Error('O backup excede o tamanho permitido.');reviewImport(JSON.parse(await file.text()),file.name);}catch(e){pendingImport=null;notify(e.message,true);}finally{ev.target.value='';}});
window.addEventListener('online',render);window.addEventListener('offline',render);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
try{doc=await readControl();render();}catch(e){document.querySelector('#app').innerHTML=welcome();notify(e.message,true);}
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').then(async()=>{await navigator.serviceWorker.ready;}).catch(()=>notify('Uso offline ainda não disponível. Abra pelo endereço HTTPS.'));
